    chatId: r[1],
    bot: r[2] || "chat",
    msgType: r[3],
    message: r[4],
    targetMessageId: r[5],
    hash: r[6],
    status: r[7],
    retryCount: r[8],
    lastError: r[9],
    createdAt: r[10],
